INSERT INTO public.catalog_products (product_id, source, name, category, product_url, image_url, description, price, currency, fit, rise, stretch, sizes, colors, raw, scraped_at, created_at, catalog_audiences) VALUES ('63198319', 'abercrombie', 'PUMA Speedcat', 'shoes', 'https://www.abercrombie.com/shop/us/p/puma-speedcat-63198319', 'https://img.abercrombie.com/is/image/anf/KIC_154-26020-00258-905_prod1?policy=product-large', 'An icon of racing culture, the PUMA Speedcat has represented speed, precision, and performance for over 25 years. Originally created as fireproof Formula 1® footwear, the silhouette has since moved beyond the track—evolving from the circuits of Monaco into a global streetwear staple. Crafted in soft suede and premium leather, and finished with a refreshed PUMA Cat logo at the front for a modern touch on a classic icon.', 100.00, 'USD', NULL, NULL, NULL, '["6", "7", "8", "9", "10", "11"]', '["zebra", "black", "red", "brown"]', '{"ld": {"sku": "154-173-00258-905", "url": "https://www.abercrombie.com/shop/us/p/puma-speedcat-63198319", "name": "PUMA Speedcat", "image": "https://img.abercrombie.com/is/image/anf/KIC_154-26020-00258-905_prod1?policy=product-large", "price": 100, "currency": "USD", "description": "An icon of racing culture, the PUMA Speedcat has represented speed, precision, and performance for over 25 years. Originally created as fireproof Formula 1® footwear, the silhouette has since moved beyond the track—evolving from the circuits of Monaco into a global streetwear staple. Crafted in soft suede and premium leather, and finished with a refreshed PUMA Cat logo at the front for a modern touch on a classic icon.", "availability": "http://schema.org/InStock"}, "sizes": {"waist": ["6", "7", "8", "9", "10", "11"], "length": []}, "colors": ["zebra", "black", "red", "brown"], "derived": {"fit": null, "rise": null, "stretch": null}, "sourceUrl": "https://www.abercrombie.com/shop/us/p/puma-speedcat-63198319"}', '2026-06-15 18:02:30.537022+00', '2026-06-15 18:02:30.537022+00', '["womens"]') ON CONFLICT DO NOTHING;
INSERT INTO public.catalog_products (product_id, source, name, category, product_url, image_url, description, price, currency, fit, rise, stretch, sizes, colors, raw, scraped_at, created_at, catalog_audiences) VALUES ('62949320', 'abercrombie', 'Sperry Authentic Original™ Women''s Mule', 'shoes', 'https://www.abercrombie.com/shop/us/p/sperry-authentic-original-mule-62949320', 'https://img.abercrombie.com/is/image/anf/KIC_154-26033-00255-445_prod1?policy=product-large', 'The slip-on boat shoe that blends iconic maritime style with everyday ease, the Sperry Authentic Original™ Mule is crafted from premium leather and finished with traditional moccasin stitching. Featuring a backless design that reimagines the classic Sperry silhouette into an effortless, on-the-go design made for real life. The EVA cushioned footbed delivers lightweight, all-day wearability and the razor-cut Wave-Siping™ non-marking rubber outsole provides dependable traction on both wet and dry surfaces. From the dock to the city streets, these boat shoe mules make getting out the door simple and stylish.', 110.00, 'USD', NULL, NULL, NULL, '["6", "7", "8", "9", "10", "11"]', '["light brown"]', '{"ld": {"sku": "154-173-00255-445", "url": "https://www.abercrombie.com/shop/us/p/sperry-authentic-original-mule-62949320", "name": "Sperry Authentic Original™ Women''s Mule", "image": "https://img.abercrombie.com/is/image/anf/KIC_154-26033-00255-445_prod1?policy=product-large", "price": 110, "currency": "USD", "description": "The slip-on boat shoe that blends iconic maritime style with everyday ease, the Sperry Authentic Original™ Mule is crafted from premium leather and finished with traditional moccasin stitching. Featuring a backless design that reimagines the classic Sperry silhouette into an effortless, on-the-go design made for real life. The EVA cushioned footbed delivers lightweight, all-day wearability and the razor-cut Wave-Siping™ non-marking rubber outsole provides dependable traction on both wet and dry surfaces. From the dock to the city streets, these boat shoe mules make getting out the door simple and stylish.", "availability": "http://schema.org/InStock"}, "sizes": {"waist": ["6", "7", "8", "9", "10", "11"], "length": []}, "colors": ["light brown"], "derived": {"fit": null, "rise": null, "stretch": null}, "sourceUrl": "https://www.abercrombie.com/shop/us/p/sperry-authentic-original-mule-62949320"}', '2026-06-15 18:02:33.655298+00', '2026-06-15 18:02:33.655298+00', '["womens"]') ON CONFLICT DO NOTHING;
INSERT INTO public.catalog_products (product_id, source, name, category, product_url, image_url, description, price, currency, fit, rise, stretch, sizes, colors, raw, scraped_at, created_at, catalog_audiences) VALUES ('62739819', 'abercrombie', 'Sperry Authentic Original™ Women''s Mule Boat Shoe', 'shoes', 'https://www.abercrombie.com/shop/us/p/sperry-authentic-original-mule-boat-shoe-62739819', 'https://img.abercrombie.com/is/image/anf/KIC_154-6075-00190-400_prod1?policy=product-large', 'A collection that first set sail in 1935—revived for today''s escape. A preppy silhouette designed for carefree wear, this mule boat shoe combines classic nautical style with slip-on ease. Crafted from supple leather with EVA cushioning and Sperry’s signature Razor Cut Wave-Siping™, it adds an effortless touch to any casual look.', 125.00, 'USD', NULL, NULL, NULL, '["6", "7", "8", "9", "10", "11"]', '["brown", "light brown"]', '{"ld": {"sku": "154-173-00190-400", "url": "https://www.abercrombie.com/shop/us/p/sperry-authentic-original-mule-boat-shoe-62739819", "name": "Sperry Authentic Original™ Women''s Mule Boat Shoe", "image": "https://img.abercrombie.com/is/image/anf/KIC_154-6075-00190-400_prod1?policy=product-large", "price": 125, "currency": "USD", "description": "A collection that first set sail in 1935—revived for today''s escape. A preppy silhouette designed for carefree wear, this mule boat shoe combines classic nautical style with slip-on ease. Crafted from supple leather with EVA cushioning and Sperry’s signature Razor Cut Wave-Siping™, it adds an effortless touch to any casual look.", "availability": "http://schema.org/InStock"}, "sizes": {"waist": ["6", "7", "8", "9", "10", "11"], "length": []}, "colors": ["brown", "light brown"], "derived": {"fit": null, "rise": null, "stretch": null}, "sourceUrl": "https://www.abercrombie.com/shop/us/p/sperry-authentic-original-mule-boat-shoe-62739819"}', '2026-06-15 18:02:36.640996+00', '2026-06-15 18:02:36.640996+00', '["womens"]')